var ArkResolutionProducts=(function(){"use strict";var t={names:{name:".fxn names",status:"building",page:"account/domains",line:"A signed name like studio.fxn that points at your site, app or identity. Only the genesis key can claim names until a public access gate exists."},gateway:{name:"Site gateway",status:"building",page:null,line:"Opens a .fxn site at label.defxn.com after checking its owner\u2019s signature. Names cannot be claimed in public yet, so few sites can use it."},code:{name:"Code manager",status:"ready",page:null,line:"Edit a deployed site\u2019s code and content. Access comes from the signed owner record."},packages:{name:"Packages",status:"ready",page:null,line:"Publish and install signed library packages by exact version. Apps ship as Bundles, not packages."},deployer:{name:"Bundles",status:"building",page:"bundledeployer",line:"Sign one exact release of a site or app, then point a name at it in Domains."},authkit:{name:"FXN ID",status:"ready",page:"account",line:"Your keys and recovery phrase, held by you. No password on a server."},broker:{name:"Identity broker",status:"ready",page:null,line:"Sign in once. Every defxn site can ask that one identity to sign."},wallet:{name:"FXN and credits",status:"building",page:"account",line:"Signed value transfers and usage credits. Balances start at genesis."},agreements:{name:"Agreements resolver",status:"building",page:"lifecycle",line:"Each side signs terms, work and receipt on its own chain. The resolver links them. Built in source. It is the earlier path, not the current direction."},resolvers:{name:"Resolvers",status:"ready",page:"resolver",line:"Publish logic at an address so anyone can run it and get the same claim."},explorer:{name:"Mesh Explorer",status:"ready",page:"explorer",line:"Read records from a development-network node and check who signed them."},networks:{name:"Named networks",status:"ready",page:"deploy",line:"Create or join a network by name. Today the name groups miners for discovery and isolates nothing else."},dao:{name:"Network DAO",status:"building",page:"dao",line:"A roster, a threshold and signed decisions for one network."},monitor:{name:"Mesh monitor",status:"building",page:"explorer",line:"Health and throughput of nodes, read in Explore on the development network."},treasury:{name:"Treasury",status:"building",page:"treasury",line:"Shared funds that move only under the group\u2019s agreed rules."}};function e(r,a,s,d,l){return{name:r,audience:a,problem:s,product:d,builds:l}}var o={WEBSITE:{audience:"Indie makers, small businesses and creators who need a site that does not lapse.",problem:"Hosting bills, yearly renewals and a domain someone else can take away.",ready:["names","gateway","code","packages","deployer"],ideas:[e("Shopfront.fxn","Small shops selling a handful of products","Store builders charge monthly and take a cut of every sale.","A one-page store under a .fxn name. Checkout is an FXN transfer agreement, so buyer and seller each keep a signed receipt.",["names","gateway","agreements","wallet"]),e("Forever portfolio","Designers, photographers and students","The portfolio disappears the month the plan is not renewed.","Drop a folder in, get a signed site at your name. Each update is a new version. Older versions still resolve for anyone who linked them.",["deployer","names","gateway"]),e("Client preview links","Freelancers and small agencies","Staging servers and shared passwords for every client review.","Every change in the code manager publishes a signed preview at its own name. The client approves by signing, and the approval is on record.",["code","gateway","broker"])]},CONTENT:{audience:"Writers, journalists, newsletter authors and podcasters.",problem:"A platform changes its rules, links break and the archive or audience is gone.",ready:["code","gateway","names","explorer"],ideas:[e("Signed newsletter","Independent writers","The email provider owns the list and can suspend it overnight.","Posts publish to the mesh under your name. Readers follow your identity, not a provider. Paid issues unlock with an FXN transfer.",["names","gateway","authkit","wallet"]),e("Provenance badge","Journalists and researchers","Readers cannot tell who wrote a piece or what changed after publication.","Each article carries a signed publication record. One click shows the author\u2019s key and every revision since.",["explorer","authkit","code"]),e("Unpullable podcast feed","Podcasters","A host deletion or policy strike takes the whole back catalogue offline.","The feed resolves from a .fxn name and episodes are addressed files, so any participating node can serve them.",["names","gateway","deployer"])]},FILES:{audience:"Freelancers, families and small teams who share sensitive files.",problem:"Files live in somebody else\u2019s account, and share links leak or expire.",ready:["authkit","broker","explorer"],ideas:[e("Client drop box","Accountants, lawyers and consultants","Clients email tax returns and contracts as plain attachments.","A drop page where files are encrypted to your key before they leave the client\u2019s browser. Both sides get a signed receipt of what was sent.",["authkit","broker","agreements"]),e("Family vault","Households","Passports, wills and deeds sit in one person\u2019s cloud folder.","Encrypted documents that any two of three family members can open together, so one lost phone does not lose the vault.",["authkit","dao"]),e("Big file handoff","Video editors and studios","Transfer services cap size, expire links and charge per gigabyte.","Send a name, not a link. The file arrives in addressed pieces from nearby peers and the receiver verifies every piece.",["names","gateway","explorer"])]},DEPLOYMENTS:{audience:"Developers and small teams shipping web apps and services.",problem:"Release servers, registry accounts and artifacts nobody can verify after the fact.",ready:["deployer","packages","code","resolvers","monitor"],ideas:[e("Signed release channels","Open-source maintainers","Users cannot tell whether a download is the build the maintainer made.","Stable and beta are names pointing at signed bundles. Installers check the signature before anything runs.",["packages","names","authkit"]),e("Rollback by name","Small product teams","A bad deploy means rebuilding the previous version under pressure.","Every deploy stays addressable. Rolling back is one signature that points the name at the last good bundle.",["deployer","names","gateway"]),e("Two-key production","Teams with compliance needs","Anyone with the deploy token can ship to production alone.","Production deploys need two of three maintainer signatures, and the approvals are kept with the release.",["dao","agreements","deployer"])]},PAYMENTS:{audience:"Freelancers, creators and small merchants paid by partners.",problem:"Processor fees, held funds, chargebacks and slow cross-border transfers.",ready:["agreements","wallet","authkit"],ideas:[e("Milestone invoices","Freelancers","Clients pay late, or dispute work that was already approved.","The invoice is an agreement with milestones. Each signed approval releases that part of the payment and leaves a receipt.",["agreements","wallet"]),e("Pay per read","Writers and API owners","Card minimums make small payments impossible, so everything becomes a subscription.","Readers spend credits per article or call. No account, no minimum, settled between the two keys.",["wallet","resolvers","gateway"]),e("Split payouts","Bands, collectives and co-authors","One person receives the money and has to divide it by hand.","Shares are agreed once. Each incoming payment splits by those shares and every payout is on record.",["agreements","wallet","explorer"])]},FINANCE:{audience:"Individuals and households keeping track of their own money.",problem:"Books scattered across apps, exported spreadsheets and nothing that proves a number.",ready:["authkit","wallet","explorer"],ideas:[e("Receipt book","Households","Tax time means digging through emails and screenshots.","Every payment leaves a signed receipt. Your ledger is built from those receipts and exports in one step.",["wallet","agreements","authkit"]),e("Shared household budget","Couples and housemates","Shared costs live in one person\u2019s spreadsheet and turn into arguments.","Shared expenses are agreed as they happen and settled monthly, with both keys on every entry.",["agreements","wallet"]),e("Proof of income","Gig workers renting or borrowing","Proving income means handing over every bank statement.","Share one checked claim, such as earned above a set amount over six months, without exposing each transaction.",["resolvers","explorer","authkit"])]},COMMUNITY:{audience:"Organisers, clubs, fan groups and member organisations.",problem:"The platform owns the member list, rents back the reach and moderates in private.",ready:["authkit","broker","explorer","networks"],ideas:[e("Member pass","Clubs and associations","Membership lives in a database the club pays for and can lose.","Membership is a signed record the member holds. Any member site checks it through the broker in one step.",["authkit","broker","explorer"]),e("Portable following","Creators with an audience","Moving platforms means starting again from zero followers.","Follows are records on the mesh, so the community comes with you to whatever tool you use next.",["explorer","names"]),e("Open moderation log","Forum and group moderators","Bans look arbitrary because nobody can see the rule behind them.","Each removal is recorded with the rule it applied, and members can dispute it.",["dao","resolvers","explorer"])]},COMMUNICATIONS:{audience:"Small teams, journalists and families who need private conversations.",problem:"The provider reads the metadata and one account lock-out cuts you off.",ready:["authkit","broker","names"],ideas:[e("Contact by name","Anyone","Reaching someone privately means swapping phone numbers.","Message alex.fxn. The message is encrypted to the keys that name publishes, and nobody in between can read it.",["names","authkit"]),e("Source line","Newsrooms","Tip forms run on servers that log who sent what.","A tip page encrypts straight to the newsroom\u2019s key. The source keeps a code to read replies without an account.",["authkit","gateway"]),e("Device-linked inbox","Small teams","A lost laptop keeps access until IT notices.","You choose which devices can read the inbox, and revoke one with a single signature from another.",["authkit","explorer"])]},COLLABORATIONS:{audience:"Agencies and clients, co-founders and open-source contributors.",problem:"Seat licences, one vendor holding the work and arguments over who did what.",ready:["code","agreements","authkit","explorer"],ideas:[e("Signed briefs","Agencies and their clients","Scope creeps because nobody can point to what was agreed.","The brief is signed by both sides. Change requests are signed amendments, and delivery ends in a receipt.",["agreements","code"]),e("Contribution ledger","Co-creators and open-source teams","Credit and revenue shares are decided from memory.","Every contribution is signed by its author, and shares are calculated from that record.",["code","agreements","wallet"]),e("Co-edited site","Sites with several authors","Everyone shares one admin password.","Grant each author edit rights to their own section. Every change carries its author\u2019s signature.",["code","authkit","broker"])]},GOVERNANCE:{audience:"Co-ops, associations, DAOs and project steering groups.",problem:"Decisions happen in chat threads and nobody can say who approved what.",ready:["dao","agreements","explorer","authkit"],ideas:[e("Proposal kit","Co-ops and associations","Votes are counted by hand and the outcome is hard to check later.","Write the rule, set the threshold, collect signatures. The decision page keeps approvals and activation evidence together.",["dao","explorer"]),e("Spending approvals","Groups that hold shared funds","One treasurer can move the money alone.","Spending above a limit needs the agreed number of signatures before the treasury will release it.",["dao","treasury","wallet"]),e("Bylaws that check themselves","Associations with formal rules","Invalid proposals reach a vote and get challenged afterwards.","The bylaws run as a resolver, so a proposal is checked against them before voting opens.",["resolvers","dao"])]},INTELLIGENCE:{audience:"Analysts, AI builders and businesses with sensitive data.",problem:"Private data gets sent to remote models and the answers cannot be checked.",ready:["resolvers","agreements","explorer"],ideas:[e("Answers with receipts","Analysts and researchers","A model answer gives no way to see what it was based on.","Each answer cites the signed records it used, so anyone can re-run the check.",["resolvers","explorer"]),e("Model beside the data","Clinics and law firms","Using AI means copying confidential files to a vendor.","Agreed logic runs on nodes next to the encrypted records. Only the result leaves, with its evidence.",["resolvers","agreements","networks"]),e("Paid inference","Independent AI builders","Selling a model means running billing, keys and accounts.","Callers agree terms and pay in credits per verified result. No customer accounts to run.",["agreements","wallet","resolvers"])]},DATA:{audience:"App developers, researchers and public-data publishers.",problem:"Running database servers and sync jobs, with no record of where a value came from.",ready:["explorer","resolvers","networks","monitor"],ideas:[e("Backend-less app data","Indie app developers","A small app still needs a database server and an admin.","The app writes signed records and reads them back from the mesh. There is no database to host.",["explorer","authkit","broker"]),e("Versioned open datasets","Researchers and public bodies","Datasets change quietly and citations stop matching.","Every version has its own address and signature, so a citation always points at the exact data used.",["explorer","names","packages"]),e("Shared record sync","Small businesses with several tools","Nightly spreadsheet exports keep tools roughly in sync.","Tools read one shared signed record instead of copying data between each other.",["explorer","agreements"])]},ALGORITHMS:{audience:"Algorithm authors, scientists and API vendors.",problem:"Opaque APIs change silently and results cannot be reproduced.",ready:["resolvers","packages","explorer"],ideas:[e("Resolver marketplace","Algorithm authors","Selling an algorithm means running an API business.","Publish it as a resolver and earn credits per call. Callers pin the exact version they trust.",["resolvers","wallet","agreements"]),e("Reproducible results","Scientists","Reviewers cannot rerun the analysis behind a paper.","The paper cites the resolver address and input. Anyone reruns it and gets the same claim.",["resolvers","explorer"]),e("Open pricing rules","Online sellers","Platform fee calculations are a black box.","Fees run as a named resolver that seller and platform both run and both get the same number.",["resolvers","agreements"])]},INFORMATION:{audience:"Documentation teams, wikis, fact-checkers and support desks.",problem:"Links break, sources go missing and nobody can see what changed.",ready:["names","gateway","code","explorer"],ideas:[e("Docs with history","Product and support teams","Customers follow an old answer that changed without notice.","Docs live at a name. Each revision is signed and anyone can compare versions.",["code","gateway","names"]),e("Source trail","Fact-checkers","A claim gets repeated until nobody knows where it started.","Each claim links to signed statements about its source, back to the original.",["explorer","authkit"]),e("Permanent citations","Students, lawyers and librarians","Cited web pages vanish within a few years.","Cite a mesh address instead. It keeps resolving to the exact page that was cited.",["names","gateway"])]},RULES:{audience:"Compliance teams, marketplace operators and competition organisers.",problem:"The same rule is read differently by each person who applies it.",ready:["resolvers","agreements","dao"],ideas:[e("Eligibility checker","Grant and benefit programmes","Applicants spend hours on forms they were never eligible for.","The criteria run as a resolver. Applicants see pass or fail, and why, before applying.",["resolvers","gateway"]),e("Marketplace policy","Marketplace operators","Sellers argue that listing rules are applied unevenly.","Listing rules are applied the same way on every node, and disputes name the exact rule version.",["resolvers","dao","explorer"]),e("Match rules","Tournament and league organisers","Results are disputed and settled by whoever runs the event.","Published rules check each result, and both teams sign the outcome.",["resolvers","agreements"])]},NETWORK:{audience:"Communities and companies that want their own network, and the people who run nodes.",problem:"Cloud accounts, fixed clusters and capacity planning before anyone joins.",ready:["networks","monitor","explorer"],ideas:[e("Network in a box","Local co-ops and communities","Running shared infrastructure needs an IT person.","Name a network and invite members\u2019 machines with a link. Capacity grows as they join.",["networks","monitor"]),e("Operator earnings","Node operators","Operators cannot see what their machine contributed or earned.","Uptime, load served and payouts, read straight from mesh records.",["monitor","explorer","wallet"]),e("Event mesh","Conferences and festivals","Event apps fall over when the venue Wi-Fi does.","A temporary network the attendees\u2019 devices form, which closes cleanly when the event ends.",["networks","authkit"])]},ENCRYPTIONS:{audience:"Professionals handling private information, and anyone who wants their own keys.",problem:"The provider holds the keys, so privacy depends on its policy.",ready:["authkit","broker"],ideas:[e("Recovery circle","Individuals","Losing the only copy of a key means losing everything.","Recovery is split between people you trust. Any three of five can restore your key together.",["authkit","dao"]),e("Time-boxed sharing","Doctors, lawyers and accountants","Shared files stay readable long after the job is done.","Encrypt to a recipient for a set window. Access ends with the agreement, and the access is on record.",["authkit","agreements"]),e("Access report","Small clinics and practices","Audits ask who could read what, and nobody can prove it.","A checked report of which keys could open which records, and when.",["authkit","explorer","resolvers"])]},AUTOMATION:{audience:"Small businesses and ops teams automating routine work.",problem:"Webhook glue and bots that hold far more access than they need.",ready:["agreements","resolvers","monitor"],ideas:[e("Paid, then delivered","Sellers of digital goods","Delivery depends on a webhook that sometimes fails.","When the payment\u2019s receipt is signed, the download or licence releases on its own.",["agreements","wallet","gateway"]),e("Scoped bots","Teams using bots","A bot token can usually do anything its owner can.","Each bot key may write to one place only, and one signature revokes it.",["authkit","explorer"]),e("Deploy on approval","Product teams","Someone has to remember to deploy after sign-off.","Once the required approvals are signed, the site\u2019s name points at the approved bundle.",["deployer","dao","names"])]},PRODUCTIVITY:{audience:"Freelancers and small teams paying for a stack of tools.",problem:"Per-seat plans, an account per app and work trapped in each one.",ready:["code","authkit","broker","gateway"],ideas:[e("One sign-in","Small teams","Every tool needs its own account and password reset.","One identity signs into every mesh tool through the broker. No per-app accounts.",["broker","authkit"]),e("Shared task board","Freelancers and their clients","Status lives in whichever tool the client happens to prefer.","Each task is a signed record both sides see, and done means both signed it.",["agreements","explorer"]),e("Forms to your records","Small businesses","Form builders hold your customers\u2019 answers on their servers.","A form published at your name. Every answer is encrypted to your key.",["gateway","names","authkit"])]},LOGISTICS:{audience:"Small shippers, couriers, importers and makers with suppliers.",problem:"Separate trackers, reconciled spreadsheets and arguments about who had the parcel.",ready:["agreements","explorer","authkit"],ideas:[e("Signed handoffs","Couriers and small carriers","Lost parcels turn into a dispute about who last had them.","Each handoff is signed by both people, so custody has a trail.",["agreements","authkit"]),e("Proof of origin","Coffee, wine and craft producers","Origin claims on the label cannot be checked.","A batch record from farm to shelf, readable by scanning the label.",["explorer","gateway","names"]),e("Pay on delivery","Importers and suppliers","Either the buyer pays upfront or the supplier waits on trust.","Payment releases when the receiver signs the delivery.",["agreements","wallet"])]}};function n(r){var a=t[r];return a?{key:r,name:a.name,status:a.status,page:a.page,line:a.line}:null}function i(r){var a=o[r];return a?{audience:a.audience,problem:a.problem,ready:a.ready.map(n).filter(Boolean),ideas:a.ideas.map(function(s){return{name:s.name,audience:s.audience,problem:s.problem,product:s.product,builds:s.builds.map(n).filter(Boolean)}})}:null}return{products:t,resolutions:o,product:n,forResolution:i}})();
